-- Naxxramas: Marauding Geists and Garden Gas, Garden Gas aura, and 25-player masks for spawns that had only 10-player.

-- Marauding Geist (25) and Garden Gas (5) spawns
DELETE FROM `creature` WHERE `guid` BETWEEN 8307000 AND 8307029;

-- Garden Gas: its poison cloud aura
DELETE FROM `creature_template_addon` WHERE `entry` = 17231;

-- Instructor Razuvious, Kel'Thuzad windows 1, 3 and 4 and his door spawned in 10-player only
UPDATE `creature` SET `spawnMask` = 24 WHERE `guid` = 128312 AND `id` = 16061 AND `map` = 533 AND `spawnMask` = 8;
UPDATE `gameobject` SET `spawnMask` = 24 WHERE `guid` IN (150155, 150157, 150158, 150159) AND `id` IN (181402, 181404, 181405, 181228) AND `map` = 533 AND `spawnMask` = 8;
